{
  "title": "The Gilded Cage Rescue",
  "scenes": [
    {
      "scene_number": 1,
      "caption": "The rescue party gathers at the forest's edge.",
      "visual_description": "A misty dawn, five figures silhouetted against the ruined skyline of a once-great city. Broken towers and faded royal banners hang limp.",
      "characters": ["Elara", "Finn", "Mara", "Kael", "Bram"]
    },
    {
      "scene_number": 2,
      "caption": "They slip past frightened townspeople fleeing the city.",
      "visual_description": "A cobblestone road clogged with refugees clutching bundles. A child cries. Elara pulls her hood lower.",
      "characters": ["Elara", "Finn", "Mara", "Kael", "Bram", "Frightened Townspeople"]
    },
    {
      "scene_number": 3,
      "caption": "A stone archway sealed by a glowing magic door.",
      "visual_description": "A towering arch etched with runes, pulsing with amber light. Mara presses her palm to it; the runes flare.",
      "characters": ["Mara", "Elara", "Finn"]
    },
    {
      "scene_number": 4,
      "caption": "Kael picks the lock of a cursed tower gate.",
      "visual_description": "A rusted iron door covered in warning plaques. Kael works a thin tool into the keyhole while shadows writhe in the tower window above.",
      "characters": ["Kael", "Elara", "Bram"]
    },
    {
      "scene_number": 5,
      "caption": "Inside the tower, they find a map room with a shifting layout.",
      "visual_description": "Circular stone room with a central pedestal holding a floating, rotating map. The walls display different districts of the ruined city.",
      "characters": ["Elara", "Finn", "Mara", "Kael", "Bram"]
    },
    {
      "scene_number": 6,
      "caption": "An armored patrol marches through the courtyard below.",
      "visual_description": "Through a narrow window, a squad of six armored soldiers in royal blue tabards clanks across cracked paving stones, spears glinting.",
      "characters": ["Armored Patrol", "Elara", "Finn"]
    },
    {
      "scene_number": 7,
      "caption": "They cross a rope bridge between two ruined towers.",
      "visual_description": "A fraying rope bridge sways over a chasm filled with rubble. Finn goes first, testing each plank. Mist curls below.",
      "characters": ["Finn", "Elara", "Mara", "Kael", "Bram"]
    },
    {
      "scene_number": 8,
      "caption": "Bram distracts a patrol with a false alarm in a market square.",
      "visual_description": "An empty market with toppled stalls. Bram knocks over a stack of barrels, creating a clatter. The patrol turns and runs toward the noise.",
      "characters": ["Bram", "Armored Patrol"]
    },
    {
      "scene_number": 9,
      "caption": "They find a hidden passage behind a royal banner.",
      "visual_description": "A tattered banner bearing the old crest is pushed aside, revealing a narrow, dark stairway spiraling downward.",
      "characters": ["Elara", "Finn", "Mara", "Kael", "Bram"]
    },
    {
      "scene_number": 10,
      "caption": "A rumor of dragons tempts them to explore a collapsed hall.",
      "visual_description": "A vast hall with a collapsed roof, sunlight streaming in. Scorch marks blacken the marble floor. A massive claw print is etched into the stone.",
      "characters": ["Mara", "Kael", "Bram", "Elara"]
    },
    {
      "scene_number": 11,
      "caption": "They unlock a magic door with a riddle carved in the frame.",
      "visual_description": "A door of black obsidian, a riddle carved in silver letters. Mara reads aloud, and the door dissolves into shimmering dust.",
      "characters": ["Mara", "Elara", "Finn", "Kael", "Bram"]
    },
    {
      "scene_number": 12,
      "caption": "The rescue target is found in a sunken throne room.",
      "visual_description": "A decrepit throne room half-flooded with green water. On the dais, chained to the throne, sits a pale figure—the prisoner.",
      "characters": ["Prisoner", "Elara", "Finn", "Mara", "Kael", "Bram"]
    },
    {
      "scene_number": 13,
      "caption": "Kael picks the locks on the prisoner's chains.",
      "visual_description": "Close-up of metal manacles around wrists and ankles. Kael's fingers work quickly, sweat on his brow. Chains clink as they fall.",
      "characters": ["Kael", "Prisoner"]
    },
    {
      "scene_number": 14,
      "caption": "The alarm sounds—patrols converge on the throne room.",
      "visual_description": "A horn blast echoes through stone corridors. Torchlight flickers from multiple entrances as armored boots pound closer.",
      "characters": ["Armored Patrol", "Elara", "Finn", "Mara", "Kael", "Bram", "Prisoner"]
    },
    {
      "scene_number": 15,
      "caption": "They fight through a narrow corridor to reach the escape route.",
      "visual_description": "A tight stone corridor, armor scraping against walls. Elara's blade clashes with a patrol sword. Sparks fly in the gloom.",
      "characters": ["Elara", "Finn", "Mara", "Kael", "Bram", "Prisoner", "Armored Patrol"]
    },
    {
      "scene_number": 16,
      "caption": "The final escape across a crumbling bridge over a dry moat.",
      "visual_description": "A narrow stone bridge, half-collapsed, spanning a deep dry moat of jagged rocks. The party runs across, stones crumbling behind their heels.",
      "characters": ["Elara", "Finn", "Mara", "Kael", "Bram", "Prisoner"]
    },
    {
      "scene_number": 17,
      "caption": "The bridge collapses behind them as they reach the far side.",
      "visual_description": "With a roar, the center of the bridge gives way, tumbling into the moat. Dust billows. The party stands panting on the grassy bank.",
      "characters": ["Elara", "Finn", "Mara", "Kael", "Bram", "Prisoner"]
    },
    {
      "scene_number": 18,
      "caption": "They vanish into the forest as the ruined city fades behind them.",
      "visual_description": "Dusk settles, the party disappears under a canopy of ancient trees. The ruined city's towers are small and distant, smoke rising from its walls.",
      "characters": ["Elara", "Finn", "Mara", "Kael", "Bram", "Prisoner"]
    }
  ]
}

